mapper.select:
select count(*) from ai_prompt_template
where prompt_code = #{promptCode} and version = #{version} and del_flag = '0'
and id != #{excludeId}

mapper.update:
update ai_prompt_template set enabled = '1', update_by = #{updateBy}, update_time = sysdate()
where prompt_code = #{promptCode} and enabled = '0' and del_flag = '0'
and id != #{excludeId}
